fn remove_odd_numbers(arr: &[i32]) -> Vec<i32> {
    // Requires that the input array is not null
    // Ensures that the output vector contains only even numbers
    // and that the length of the output vector is less than or equal to the length of the input array
    // Invariant: The even_numbers vector contains only even numbers at all times during the loop
    // Decreases clause: The length of the input array decreases with each iteration
    // The function is specified to ensure that it behaves correctly according to the requirements.

    // Create a new vector to hold the even numbers
    let mut even_numbers = Vec::new();

    // Iterate over the input array
    for &num in arr.iter() {
        // Check if the number is even
        if num % 2 == 0 {
            // If it is even, push it to the new vector
            even_numbers.push(num);
        }
    }

    // Return the vector containing only even numbers
    even_numbers
}

